import { API_KEY_RESOURCES } from '@/constants.ee';
import { GLOBAL_ADMIN_SCOPES, GLOBAL_OWNER_SCOPES } from '@/roles/scopes/global-scopes.ee';
import {
	PERSONAL_PROJECT_OWNER_SCOPES,
	PROJECT_EDITOR_SCOPES,
	PROJECT_VIEWER_SCOPES,
	REGULAR_PROJECT_ADMIN_SCOPES,
} from '@/roles/scopes/project-scopes.ee';
import type { AuthPrincipal } from '@/types.ee';
import { hasGlobalScope } from '@/utilities/has-global-scope.ee';

const principal = (slug: string, scopes: string[]): AuthPrincipal =>
	({
		role: { slug, scopes: scopes.map((scope) => ({ slug: scope })) },
	}) as unknown as AuthPrincipal;

describe('credentialTypePolicy:manage and nodeTypePolicy:manage are independent scopes', () => {
	it('a user granted only nodeTypePolicy:manage does not also gain credentialTypePolicy:manage', () => {
		expect(
			hasGlobalScope(
				principal('custom:node-policy-manager-only', ['nodeTypePolicy:manage']),
				'credentialTypePolicy:manage',
			),
		).toBe(false);
	});

	it('a user granted only credentialTypePolicy:manage does not also gain nodeTypePolicy:manage', () => {
		expect(
			hasGlobalScope(
				principal('custom:credential-policy-manager-only', ['credentialTypePolicy:manage']),
				'nodeTypePolicy:manage',
			),
		).toBe(false);
	});
});

describe('credentialTypePolicy:manage default grants', () => {
	it('is granted to instance owners and admins', () => {
		expect(GLOBAL_OWNER_SCOPES).toContain('credentialTypePolicy:manage');
		expect(GLOBAL_ADMIN_SCOPES).toContain('credentialTypePolicy:manage');
	});

	it('is granted to project admins, same as nodeTypePolicy:manage', () => {
		expect(REGULAR_PROJECT_ADMIN_SCOPES).toContain('credentialTypePolicy:manage');
	});

	it('is not granted to personal project owners, editors, or viewers', () => {
		expect(PERSONAL_PROJECT_OWNER_SCOPES).not.toContain('credentialTypePolicy:manage');
		expect(PROJECT_EDITOR_SCOPES).not.toContain('credentialTypePolicy:manage');
		expect(PROJECT_VIEWER_SCOPES).not.toContain('credentialTypePolicy:manage');
	});
});

describe('credentialTypePolicy:manage as an API key scope', () => {
	it('is not declared in API_KEY_RESOURCES yet, since no Public API endpoint consumes it', () => {
		expect(API_KEY_RESOURCES).not.toHaveProperty('credentialTypePolicy');
	});
});

import { API_KEY_RESOURCES } from '@/constants.ee';
import {
	MEMBER_API_KEY_SCOPES,
	OWNER_API_KEY_SCOPES,
	getApiKeyScopesForRole,
	getOwnerOnlyApiKeyScopes,
} from '@/public-api-permissions.ee';
import { GLOBAL_ADMIN_SCOPES, GLOBAL_OWNER_SCOPES } from '@/roles/scopes/global-scopes.ee';
import {
	PERSONAL_PROJECT_OWNER_SCOPES,
	PROJECT_EDITOR_SCOPES,
	PROJECT_VIEWER_SCOPES,
	REGULAR_PROJECT_ADMIN_SCOPES,
} from '@/roles/scopes/project-scopes.ee';
import { isApiKeyScope, type AuthPrincipal } from '@/types.ee';

describe('nodeTypePolicy:manage default grants', () => {
	it('is granted to instance owners and admins', () => {
		expect(GLOBAL_OWNER_SCOPES).toContain('nodeTypePolicy:manage');
		expect(GLOBAL_ADMIN_SCOPES).toContain('nodeTypePolicy:manage');
	});

	it('is granted to project admins, per IAM-1142 (project admins self-govern their own row)', () => {
		expect(REGULAR_PROJECT_ADMIN_SCOPES).toContain('nodeTypePolicy:manage');
	});

	it('is not granted to personal project owners, editors, or viewers', () => {
		expect(PERSONAL_PROJECT_OWNER_SCOPES).not.toContain('nodeTypePolicy:manage');
		expect(PROJECT_EDITOR_SCOPES).not.toContain('nodeTypePolicy:manage');
		expect(PROJECT_VIEWER_SCOPES).not.toContain('nodeTypePolicy:manage');
	});
});

describe('nodeTypePolicy:manage as an API key scope', () => {
	const principal = (slug: string, scopes: string[]): AuthPrincipal =>
		({
			role: { slug, scopes: scopes.map((scope) => ({ slug: scope })) },
		}) as unknown as AuthPrincipal;

	it('is declared in API_KEY_RESOURCES', () => {
		expect(API_KEY_RESOURCES.nodeTypePolicy).toEqual(['manage']);
		expect(isApiKeyScope('nodeTypePolicy:manage')).toBe(true);
	});

	it('is granted to an owner key by default', () => {
		expect(OWNER_API_KEY_SCOPES).toContain('nodeTypePolicy:manage');
		expect(getApiKeyScopesForRole(principal('global:owner', [...GLOBAL_OWNER_SCOPES]))).toContain(
			'nodeTypePolicy:manage',
		);
	});

	it('is mintable by a member so a project admin can reach the project routes', () => {
		expect(MEMBER_API_KEY_SCOPES).toContain('nodeTypePolicy:manage');
		expect(getApiKeyScopesForRole(principal('global:member', []))).toContain(
			'nodeTypePolicy:manage',
		);
	});

	it('is therefore not stripped from keys on demotion to member', () => {
		expect(getOwnerOnlyApiKeyScopes()).not.toContain('nodeTypePolicy:manage');
	});
});

import type { NativeAcpxPermissionMode } from "../../contracts/native-execution.js";
import { paperclipSemanticAction } from "../../catalog/semantic-action-catalog.js";
import { capabilityCanonicalOperation } from "../../catalog/canonical-operations.js";
import { canonicalRunnerToolName } from "../runner-tool-bridge.js";
import type { QualifiedAcpxAgent } from "./qualified-profiles.js";

export class AcpxApprovalRequiredError extends Error {
  readonly code = "approval_required";
  constructor() {
    super(
      "Approval required. This operation is not an automatically allowed Paperclip action, " +
      "and this runner has no interactive approval handler. Review the operation and " +
      "update the agent's permission setting before retrying.",
    );
    this.name = "AcpxApprovalRequiredError";
  }
}

// Review additions explicitly: a newly catalogued mutation must not inherit
// automatic provider permission. These operations implement the bounded plan,
// task, and handoff workflow; governance decisions, generic APIs, and workspace
// controls deliberately stay outside it. Asking a human does not approve work.
const AUTOMATIC_PAPERCLIP_WORKFLOW_ACTIONS = new Set([
  "report_progress", "answer_status_question", "write_document",
  "request_human_input", "register_deliverable", "finish_task", "block_task",
  "request_review", "create_task", "reassign_task", "set_dependencies",
  "create_project", "request_approval",
]);

/** Exact SDK rules for the run's runner-owned Paperclip MCP connection. */
export function claudePaperclipPermissionRules(
  tools: readonly Readonly<Record<string, unknown>>[],
  mode: NativeAcpxPermissionMode,
): string[] {
  if (mode !== "approve-reads" && mode !== "approve-paperclip") return [];
  const names = tools.flatMap((tool) => {
    if (typeof tool.name !== "string") return [];
    const name = canonicalRunnerToolName(tool.name);
    // Effects come from Paperclip's implementation catalog, never tool hints
    // or the provider's permission-request metadata. Unknown operations stay
    // subject to approval even when their names or annotations claim a read.
    const action = paperclipSemanticAction(name);
    // The semantic catalog groups approval reads under "governance". The
    // canonical side-effect class distinguishes those reads from decisions.
    const liveAction = capabilityCanonicalOperation(name);
    const isRead = liveAction
      ? liveAction.surfaces.includes("live") && liveAction.sideEffectClass === "read"
      : action?.effect === "read";
    // This only bypasses the provider's redundant permission prompt. The
    // authenticated bridge and controller still validate run authority,
    // company scope, claims, task mode, and governed-action approvals.
    return isRead || (action && (
      mode === "approve-paperclip" && AUTOMATIC_PAPERCLIP_WORKFLOW_ACTIONS.has(name)
    ))
      ? [`mcp__paperclip__${name}`]
      : [];
  });
  return [...new Set(names)].sort();
}

export interface AcpxPermissionRequestLike {
  inferredKind?: unknown;
  raw?: unknown;
}

export type AcpxPermissionDisposition =
  "allow_once" | "reject_once" | "delegate";

export interface AcpxPermissionPolicyOptions {
  /** Descriptive configuration only; never proof that a request is authorized. */
  runnerOwnedMcpServerNames?: ReadonlySet<string>;
  /** Descriptive configuration only; never proof that a request is authorized. */
  allConfiguredMcpServersAreRunnerOwned?: boolean;
}

export interface AcpxRuntimePermissionPolicy {
  autoApprove?: readonly string[];
  escalate?: readonly string[];
  defaultAction: "approve" | "deny" | "escalate";
}

export function acpxRuntimePermissionPolicy(
  mode: NativeAcpxPermissionMode,
): AcpxRuntimePermissionPolicy {
  if (mode === "approve-all") return { defaultAction: "approve" };
  if (mode === "deny-all") return { defaultAction: "deny" };
  // ACPX derives permission kinds from provider-originated requests. Until the
  // host can bind a request to independent authority, no kind is safe to
  // auto-approve here. Assigned Paperclip actions are allowed earlier at the
  // Claude SDK dispatch boundary. Other requests require an approval handler.
  return { defaultAction: "escalate" };
}

/**
 * Decide the local part of an ACP permission request. `delegate` means the
 * caller must ask the coordinator and fail closed when no delegate exists.
 */
export function decideAcpxPermission(
  _agent: QualifiedAcpxAgent,
  mode: NativeAcpxPermissionMode,
  _request: AcpxPermissionRequestLike,
  _options: AcpxPermissionPolicyOptions = {},
): AcpxPermissionDisposition {
  if (mode === "deny-all") return "reject_once";
  if (mode === "approve-all") return "allow_once";
  // inferredKind and raw semantic/MCP metadata both originate outside the
  // runner trust boundary. Neither can grant local semantic authority.
  // Assigned Paperclip actions use exact SDK rules on the runner-owned MCP
  // connection. Anything reaching this fallback still requires approval.
  return "delegate";
}

import { describe, expect, it } from "vitest";
import { capabilityCanonicalOperationsForSurface } from "../../catalog/canonical-operations.js";

import {
  acpxRuntimePermissionPolicy,
  claudePaperclipPermissionRules,
  decideAcpxPermission,
} from "./permission-policy.js";

describe("ACPX permission policy", () => {
  it.each(["approve-reads", "approve-paperclip"] as const)("allows assigned canonical live reads, including approval lookup, in %s", mode => {
    const reads = capabilityCanonicalOperationsForSurface("live").filter(action => action.sideEffectClass === "read");
    expect(reads.some(action => action.operationId === "get_approval")).toBe(true);
    for (const action of reads) {
      expect(claudePaperclipPermissionRules([{ name: action.operationId }], mode)).toEqual([`mcp__paperclip__${action.operationId}`]);
    }
    expect(claudePaperclipPermissionRules([{ name: "get_approval" }], "deny-all")).toEqual([]);
  });
  it("uses only catalogued reads assigned to this run, regardless of tool hints", () => {
    const tools = [
      "paperclip__get_task_context", "read_document", "write_document",
      "call_api", "request_approval", "unknown_read", "mcp__other__get_task_context",
    ].map((name) => ({ name, annotations: { readOnlyHint: true, effect: "read" } }));
    expect(claudePaperclipPermissionRules(tools, "approve-reads")).toEqual([
      "mcp__paperclip__get_task_context", "mcp__paperclip__read_document",
    ]);
    expect(claudePaperclipPermissionRules([], "approve-reads")).toEqual([]);
  });

  it("allows assigned Paperclip mutations without admitting unknown or external tools", () => {
    const tools = ["paperclip__write_document", "create_task", "reassign_task", "request_approval",
      "write_document", "mcp__other__create_task", "Bash", "unknown_write", "mcp__paperclip__create_task",
      "decide_approval", "control_workspace_service", "call_api", "create_skill", "schedule_wake"]
      .map(name => ({ name, annotations: { readOnlyHint: true } }));
    expect(claudePaperclipPermissionRules(tools, "approve-paperclip")).toEqual([
      "mcp__paperclip__create_task", "mcp__paperclip__reassign_task",
      "mcp__paperclip__request_approval", "mcp__paperclip__write_document",
    ]);
    expect(claudePaperclipPermissionRules([], "approve-paperclip")).toEqual([]);
    expect(claudePaperclipPermissionRules(tools, "deny-all")).toEqual([]);
  });

  it("maps each configured mode to a closed ACP runtime policy", () => {
    expect(acpxRuntimePermissionPolicy("approve-all")).toEqual({
      defaultAction: "approve",
    });
    expect(acpxRuntimePermissionPolicy("deny-all")).toEqual({
      defaultAction: "deny",
    });
    expect(acpxRuntimePermissionPolicy("approve-paperclip")).toEqual({ defaultAction: "escalate" });
    expect(acpxRuntimePermissionPolicy("approve-reads")).toEqual({
      defaultAction: "escalate",
    });
  });

  it.each([
    ["approve-all", "execute", "allow_once"],
    ["approve-reads", "read", "delegate"],
    ["approve-reads", "search", "delegate"],
    ["approve-reads", "execute", "delegate"],
    ["approve-paperclip", "read", "delegate"],
    ["approve-paperclip", "write", "delegate"],
    ["approve-paperclip", "execute", "delegate"],
    ["deny-all", "read", "reject_once"],
  ] as const)("%s maps %s to %s", (mode, inferredKind, expected) => {
    expect(
      decideAcpxPermission("claude", mode, { inferredKind, raw: {} }),
    ).toBe(expected);
  });

  it("keeps deny-all closed against provider-supplied semantic metadata", () => {
    for (const [agent, raw] of [
      ["claude", { toolCall: { name: "mcp__paperclip__paperclip_finish" } }],
      ["claude", { toolCall: { rawInput: { serverName: "paperclip" } } }],
      [
        "codex",
        {
          _meta: { is_mcp_tool_approval: true },
          toolCall: { title: "MCP approval" },
        },
      ],
    ] as const) {
      expect(
        decideAcpxPermission(
          agent,
          "deny-all",
          { inferredKind: "execute", raw },
          { allConfiguredMcpServersAreRunnerOwned: true },
        ),
      ).toBe("reject_once");
    }
  });

  it.each(["approve-reads", "approve-paperclip"] as const)("does not let provider metadata widen %s", (mode) => {
    for (const [agent, inferredKind, raw, options] of [
      [
        "codex",
        "execute",
        {
          _meta: { is_mcp_tool_approval: true },
          toolCall: { title: "MCP approval" },
        },
        { allConfiguredMcpServersAreRunnerOwned: true },
      ],
      [
        "claude",
        "write",
        { toolCall: { rawInput: { serverName: "paperclip" } } },
        {},
      ],
      [
        "claude",
        "execute",
        { toolCall: { name: "mcp__paperclip__paperclip_finish" } },
        {},
      ],
      [
        "claude",
        "write",
        {
          toolCall: {
