import type {
	AgentSideConnection,
	PermissionOption,
	PermissionOptionKind,
	RequestPermissionRequest,
	ToolCallUpdate,
} from "@agentclientprotocol/sdk";
import type { ToolApprovalRequest, ToolApprovalResult } from "@cline/shared";
import { buildToolTitle, mapToolKind } from "./tool-utils";

// ---------------------------------------------------------------------------
// Standard permission options presented to the user
// ---------------------------------------------------------------------------

const PERMISSION_OPTIONS: PermissionOption[] = [
	{
		optionId: "allow_once",
		name: "Allow once",
		kind: "allow_once" as PermissionOptionKind,
	},
	{
		optionId: "allow_always",
		name: "Allow always",
		kind: "allow_always" as PermissionOptionKind,
	},
	{
		optionId: "reject_once",
		name: "Reject",
		kind: "reject_once" as PermissionOptionKind,
	},
];

// ---------------------------------------------------------------------------
// Translate a CLI tool approval request into an ACP permission request
// ---------------------------------------------------------------------------

export function translateToolToPermissionRequest(
	request: ToolApprovalRequest,
	sessionId: string,
): RequestPermissionRequest {
	const toolCall: ToolCallUpdate = {
		toolCallId: request.toolCallId,
		title: buildToolTitle(request.toolName, request.input),
		kind: mapToolKind(request.toolName),
		status: "pending",
		rawInput: request.input,
	};

	return {
		sessionId,
		toolCall,
		options: PERMISSION_OPTIONS,
	};
}

// ---------------------------------------------------------------------------
// Interpret the ACP permission response
// ---------------------------------------------------------------------------

export function handlePermissionResponse(
	outcome:
		| {
				outcome: "cancelled";
		  }
		| {
				outcome: "selected";
				optionId: string;
		  },
): ToolApprovalResult {
	if (outcome.outcome === "cancelled") {
		return { approved: false, reason: "Permission request was cancelled" };
	}

	const optionId = outcome.optionId;
	switch (optionId) {
		case "allow_once":
		case "allow_always":
			return { approved: true };
		case "reject_once":
		case "reject_always":
			return { approved: false, reason: "User rejected the tool call" };
		default:
			return {
				approved: false,
				reason: `Unknown permission option: ${optionId}`,
			};
	}
}

// ---------------------------------------------------------------------------
// Combined: request permission from the ACP client and return CLI result
// ---------------------------------------------------------------------------

export async function requestAcpToolApproval(
	conn: AgentSideConnection,
	sessionId: string,
	request: ToolApprovalRequest,
): Promise<ToolApprovalResult> {
	const permissionRequest = translateToolToPermissionRequest(
		request,
		sessionId,
	);

	// Emit a tool_call update with "pending" status before requesting permission
	void conn.sessionUpdate({
		sessionId,
		update: {
			...permissionRequest.toolCall,
			sessionUpdate: "tool_call_update",
		},
	});

	let response: Awaited<ReturnType<AgentSideConnection["requestPermission"]>>;
	try {
		response = await conn.requestPermission(permissionRequest);
	} catch {
		return { approved: false, reason: "Permission request failed" };
	}

	const result = handlePermissionResponse(response.outcome);

	// Emit a tool_call_update reflecting the decision
	void conn.sessionUpdate({
		sessionId,
		update: {
			sessionUpdate: "tool_call_update",
			toolCallId: request.toolCallId,
			status: result.approved ? "in_progress" : "failed",
		},
	});

	return result;
}

import type { ToolApprovalRequest, ToolApprovalResult } from "@cline/shared";
import type { Config } from "../../utils/types";
import {
	applyInteractiveAutoApproveOverride,
	cloneToolPolicies,
	resolveInteractiveAutoApprovePolicy,
} from "../tool-policies";

export interface InteractiveRuntimeRefs {
	tuiToolApprover: {
		current:
			| ((request: ToolApprovalRequest) => Promise<ToolApprovalResult>)
			| null;
	};
	tuiAskQuestion: {
		current: ((question: string, options: string[]) => Promise<string>) | null;
	};
}

export function createInteractiveApprovalController(config: Config) {
	const autoApproveAllRef = {
		current: config.toolPolicies["*"]?.autoApprove !== false,
	};
	const baselineToolPolicies = cloneToolPolicies(config.toolPolicies);
	const refs: InteractiveRuntimeRefs = {
		tuiToolApprover: { current: null },
		tuiAskQuestion: { current: null },
	};

	const setInteractiveAutoApprove = (enabled: boolean) => {
		autoApproveAllRef.current = enabled;
		applyInteractiveAutoApproveOverride({
			targetPolicies: config.toolPolicies,
			baselinePolicies: baselineToolPolicies,
			enabled,
		});
	};

	const requestToolApproval = async (
		request: ToolApprovalRequest,
	): Promise<ToolApprovalResult> => {
		if (autoApproveAllRef.current) {
			return { approved: true };
		}
		if (request.policy?.autoApprove === true) {
			return { approved: true };
		}
		if (refs.tuiToolApprover.current) {
			return refs.tuiToolApprover.current(request);
		}
		return { approved: false };
	};

	return {
		autoApproveAllRef,
		setInteractiveAutoApprove,
		requestToolApproval,
		resolveToolPolicy: (toolName: string) =>
			resolveInteractiveAutoApprovePolicy({
				toolName,
				baselinePolicies: baselineToolPolicies,
				enabled: autoApproveAllRef.current,
			}),
		...refs,
	};
}

"""Deterministic approval flow for a side-effecting tool.

This example uses a local mock model, so it runs without provider credentials.
The same boundary applies to email, payments, database writes, and other
side-effecting tools: the tool body must not run until the requirement is
confirmed.
"""

import json
from typing import Any, AsyncIterator, Iterator

from agno.agent import Agent
from agno.db.in_memory import InMemoryDb
from agno.models.base import Model
from agno.models.response import ModelResponse
from agno.tools import tool

published_reports: list[str] = []


@tool(requires_confirmation=True)
def publish_report(title: str) -> str:
    """Publish a report after the user approves the side effect."""
    published_reports.append(title)
    return f"Published {title!r}."


class DeterministicModel(Model):
    """Return one tool call, then a final response, without network access."""

    def __init__(self) -> None:
        super().__init__(id="deterministic-approval-demo", provider="local")
        self._calls = 0

    def invoke(self, *args: Any, **kwargs: Any) -> ModelResponse:
        self._calls += 1
        if self._calls == 1:
            return ModelResponse(
                tool_calls=[
                    {
                        "id": "publish-1",
                        "type": "function",
                        "function": {
                            "name": "publish_report",
                            "arguments": json.dumps({"title": "Weekly status"}),
                        },
                    }
                ]
            )
        return ModelResponse(content="The approval flow is complete.")

    async def ainvoke(self, *args: Any, **kwargs: Any) -> ModelResponse:
        return self.invoke(*args, **kwargs)

    def invoke_stream(self, *args: Any, **kwargs: Any) -> Iterator[ModelResponse]:
        yield self.invoke(*args, **kwargs)

    async def ainvoke_stream(
        self, *args: Any, **kwargs: Any
    ) -> AsyncIterator[ModelResponse]:
        yield await self.ainvoke(*args, **kwargs)

    def _parse_provider_response(self, response: Any, **kwargs: Any) -> ModelResponse:
        return response

    def _parse_provider_response_delta(self, response: Any) -> ModelResponse:
        return response


def run_case(approve: bool) -> None:
    agent = Agent(
        model=DeterministicModel(),
        tools=[publish_report],
        db=InMemoryDb(),
    )
    response = agent.run("Publish the weekly status report.")
    assert response.is_paused, "The side-effecting tool should require approval."

    for requirement in response.active_requirements:
        if requirement.needs_confirmation:
            if approve:
                requirement.confirm()
            else:
                requirement.reject("The report is not ready to publish.")

    response = agent.continue_run(
        run_id=response.run_id,
        requirements=response.requirements,
    )
    assert not response.is_paused


if __name__ == "__main__":
    published_reports.clear()
    run_case(approve=False)
    assert published_reports == [], "Rejected calls must not execute the tool."

    run_case(approve=True)
    assert published_reports == ["Weekly status"]
    print("Rejected call skipped the side effect; approved call published once.")

